/* 0x0c020f00  size 0x116  file by match with source
 * confidence: observed
 * extent: 0x14e
 * evidence: a small state machine in test_exit_state: state 0 waits for the switch bits 0x10000004 (input_merged_pressed; bit 2 is the JVS TEST switch, per jvs_node_input_read) and gives each card unit card_unit_ok accepts 300 frames in test_exit_card_wait; state 1 counts those down (ending early when the unit is idle and its card_status byte is 0); state 2 shuts down (net_shutdown, break_ab_clear, sound_all_off, g1_bus_hold, elan_regs_quiesce) and calls bios_helper_44, which hands the board to the BIOS; callers game_frame_loop, game_boot and the two halt screens; part of vf4lib/libbase/src/system.c; observed live 2026-11-10: in the harness scenario test_switch (the switch pressed, no pokes) input_merged_pressed(0x10000004) returned 0 in 413 frames and 4, the TEST bit, at vertical blank 6677; that call asked card_unit_ok about both units (0 for each: the harness has no card reader, so no 300-frame wait was given and the countdown body of state 1 did not run), and the next frame's call made net_shutdown, break_ab_clear, sound_all_off, g1_bus_hold, elan_regs_quiesce and bios_helper_44 in that order; bios_helper_44 left for the BIOS (0xAC018188) and nothing returned; in every other scenario the switch word stayed 0 and only the waiting state ran
 * matched: source/vf4lib/libbase/src/system.c (tools/match/match.py)
 */
void test_switch_exit_to_bios(void)
{
  typedef struct { char a; uchar b; char p[6]; } ent;
  int i;

  switch (test_exit_state) {
  case 0:
    if (input_merged_pressed(0x10000004) == 0) break;
    test_exit_state = 1;
    for (i = 0; i < 2; i++) {
      if (card_unit_ok(i)) {
        char *c = card_unit_used;
        char z = 0;
        int *a = &test_exit_card_wait;
        c[i] = z;
        a[i] = 300;
      }
      else {
        int *a = &test_exit_card_wait;
        a[i] = 0;
      }
    }
    break;
  case 1:
    for (i = 0; i < 2; i++) {
      int *a = &test_exit_card_wait;
      int *q = &a[i];
      if (*q > 0) {
        if (card_unit_result(i) != 1) {
          ent *e = (ent *)&card_status;
          if (e[i].b == 0) { *q = 0; continue; }
        }
        {
          int *d = &test_exit_card_wait;
          d[i]--;
        }
      }
    }
    if ((&test_exit_card_wait)[0] <= 0 && (&test_exit_card_wait)[1] <= 0)
      test_exit_state = 2;
    break;
  }
  if (test_exit_state == 2) {
    test_exit_state = 0;
    net_shutdown();
    break_ab_clear();
    sound_all_off();
    g1_bus_hold();
    elan_regs_quiesce();
    bios_helper_44();
  }
}

